/**
 * Builds src/data/puzzles.ts from the pictures in scripts/art.ts plus a few
 * seeded generated patterns, and verifies that every puzzle has exactly one
 * solution. Deterministic: running it twice produces the same file.
 *
 *   npm run generate:puzzles
 *
 * The deployed site only reads the generated file; it never runs this script.
 */
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { cluesFromGrid, gridFromSolution, solutionFromGrid } from '../src/engine/clues';
import { generatePuzzle, makeUnique, mulberry32 } from '../src/engine/generator';
import { solve } from '../src/engine/solver';
import { FILLED, type Difficulty, type Grid, type Puzzle } from '../src/types/puzzle';
import { advanced, beginner, easy, intermediate, type ArtEntry } from './art';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');

/** Prefer changing cells on the edge of a shape: they disturb the picture least. */
function boundaryRank(width: number, height: number) {
  return (cell: number, grid: Grid): number => {
    const r = Math.floor(cell / width);
    const c = cell % width;
    let unlike = 0;
    for (let dr = -1; dr <= 1; dr++)
      for (let dc = -1; dc <= 1; dc++) {
        const rr = r + dr;
        const cc = c + dc;
        if ((dr || dc) && rr >= 0 && cc >= 0 && rr < height && cc < width) {
          if ((grid[rr * width + cc] === FILLED) !== (grid[cell] === FILLED)) unlike++;
        }
      }
    return -unlike;
  };
}

const report: string[] = [];
const puzzles: Puzzle[] = [];
let number = 0;

function addPuzzle(id: string, name: string, note: string, difficulty: Difficulty, grid: Grid, width: number, height: number) {
  const clues = cluesFromGrid(grid, width, height);
  const res = solve(clues, { maxSolutions: 2 });
  if (!res.uniqueProven) throw new Error(`${id}: not proven unique (${res.status})`);
  number++;
  puzzles.push({
    id,
    name,
    note,
    difficulty,
    width,
    height,
    rows: clues.rows,
    cols: clues.cols,
    solution: solutionFromGrid(grid, width, height),
    unique: true,
    source: 'library',
    number,
    solvedBy: res.logicOnly ? 'line-logic' : 'search',
  });
  report.push(
    `- ${id} (${width}x${height}): unique, ${res.logicOnly ? 'line logic only' : `needs search (${res.branches} branches)`}`,
  );
}

function addArt(prefix: string, difficulty: Difficulty, entries: ArtEntry[], size: number) {
  entries.forEach((entry, i) => {
    if (entry.rows.length !== size || entry.rows.some((r) => r.length !== size)) {
      throw new Error(`${entry.name}: expected ${size}x${size}`);
    }
    const { grid } = gridFromSolution(entry.rows);
    const fixed = makeUnique(grid, size, size, { rank: boundaryRank(size, size), maxIterations: 30 });
    if (!fixed.unique) throw new Error(`${entry.name}: could not make unique`);
    const id = `${prefix}${String(i + 1).padStart(2, '0')}-${entry.slug}`;
    if (fixed.flips.length > 0) {
      const where = fixed.flips.map((c) => `r${Math.floor(c / size) + 1}c${(c % size) + 1}`).join(', ');
      report.push(`- ${id}: changed ${fixed.flips.length} cell(s) from the drawing to make it unique: ${where}`);
    }
    addPuzzle(id, entry.name, entry.note, difficulty, fixed.grid, size, size);
  });
}

addArt('b', 'beginner', beginner, 5);
addArt('e', 'easy', easy, 8);
addArt('i', 'intermediate', intermediate, 10);
addArt('a', 'advanced', advanced, 15);

// Generated studies fill the advanced tier. They are abstract and named as such.
const seeds = mulberry32(0x5eed);
let study = 0;
while (puzzles.filter((p) => p.difficulty === 'advanced').length < 10) {
  const seed = Math.floor(seeds() * 0xffffffff);
  const mirror = study % 2 === 0;
  const g = generatePuzzle(15, 15, seed, { density: 0.52, smoothing: 2, mirror });
  if (!g) continue;
  study++;
  addPuzzle(
    `a-study-${seed.toString(16)}`,
    `Họa tiết ${study}`,
    `Họa tiết trừu tượng được tạo từ mã khởi tạo ${seed.toString(16)}${mirror ? ', đối xứng' : ''}.`,
    'advanced',
    g.grid,
    15,
    15,
  );
}

const header = `// Generated by scripts/generate-puzzles.ts. Do not edit by hand.
// Every puzzle below was verified to have exactly one solution.
import type { Puzzle } from '../types/puzzle';
import { FINAL_BOSS } from './finalBoss';

`;
writeFileSync(
  join(root, 'src/data/puzzles.ts'),
  header + `const BASE_LIBRARY: Puzzle[] = ${JSON.stringify(puzzles, null, 1)};\n\nexport const LIBRARY: Puzzle[] = [...BASE_LIBRARY, FINAL_BOSS];\n`,
);
writeFileSync(
  join(root, 'scripts/generation-report.md'),
  `# Puzzle generation report\n\n${puzzles.length} puzzles written to src/data/puzzles.ts.\n\n${report.join('\n')}\n`,
);
console.log(report.join('\n'));
console.log(`\n${puzzles.length} puzzles written.`);
